import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int x = 0;
        int y = 0;
        Set<Cell> visited = new HashSet<>();
        Map<Cell, Integer> visits = new HashMap<>();
        visited.add(new Cell(x, y));
        visits.merge(new Cell(x, y), 1, Integer::sum);
        for (int i = 0; i < n; i++) {
            switch (sc.next()) {
                case "U" -> y++;
                case "D" -> y--;
                case "L" -> x--;
                default -> x++;
            }
            visited.add(new Cell(x, y));
            visits.merge(new Cell(x, y), 1, Integer::sum);
        }
        System.out.println("Distinct cells: " + visited.size());
        System.out.println("Start visits: " + visits.getOrDefault(new Cell(0, 0), 0));
        System.out.println("Visited (1, 1): " + visited.contains(new Cell(1, 1)));
    }
}

