import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.Scanner;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Version> versions = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.next().split("\\.");
            versions.add(new Version(Integer.parseInt(parts[0]), Integer.parseInt(parts[1])));
        }
        Collections.sort(versions);
        System.out.println("Sorted: " + versions);
        Set<Version> unique = new TreeSet<>(versions);
        System.out.println("Unique: " + unique.size() + " " + unique);
        List<Version> newest = new ArrayList<>(unique);
        newest.sort(Collections.reverseOrder());
        System.out.println("Newest first: " + newest);
    }
}

class Version implements Comparable<Version> {
    private final int major;
    private final int minor;

    Version(int major, int minor) {
        this.major = major;
        this.minor = minor;
    }

    @Override
    public int compareTo(Version other) {
        int byMajor = Integer.compare(major, other.major);
        if (byMajor != 0) {
            return byMajor;
        }
        return Integer.compare(minor, other.minor);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Version)) {
            return false;
        }
        Version other = (Version) o;
        return major == other.major && minor == other.minor;
    }

    @Override
    public int hashCode() {
        return Objects.hash(major, minor);
    }

    @Override
    public String toString() {
        return major + "." + minor;
    }
}

