import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.Scanner;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Runner> runners = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            runners.add(new Runner(sc.next(), sc.nextInt()));
        }
        Set<Runner> finishers = new TreeSet<>(runners);
        System.out.println("Runners: " + finishers.size());
        int place = 1;
        for (Runner r : finishers) {
            if (place > 3) {
                break;
            }
            System.out.println(place + ". " + r);
            place++;
        }
        List<Runner> byName = new ArrayList<>(finishers);
        byName.sort(Comparator.comparing(Runner::getName));
        System.out.println("By name: " + byName);
    }
}

class Runner implements Comparable<Runner> {
    private final String name;
    private final int time;

    Runner(String name, int time) {
        this.name = name;
        this.time = time;
    }

    String getName() {
        return name;
    }

    @Override
    public int compareTo(Runner other) {
        int byTime = Integer.compare(time, other.time);
        if (byTime != 0) {
            return byTime;
        }
        return name.compareTo(other.name);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Runner)) {
            return false;
        }
        Runner other = (Runner) o;
        return time == other.time && name.equals(other.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, time);
    }

    @Override
    public String toString() {
        return name + " " + time;
    }
}
